"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["34954"],{92616(e){e.exports=JSON.parse('{"id":"FIN-1293","slug":"iban","term":"IBAN","also_known_as":[],"difficulty":"Advanced","definition":"An IBAN, or International Bank Account Number, is a standard international format for identifying a bank account, used to make cross-border payments more accurate and efficient.","explanation":["Different countries use different formats for bank account numbers, which can lead to errors in international payments. The IBAN standardises the format, including a country code, check digits and the domestic account details.","An IBAN can be up to 34 characters long. It starts with a two-letter country code, followed by two check digits that help detect typing errors, and then the domestic bank and account information. For example, an IBAN might begin with DE for Germany or FR for France.","IBANs are used throughout Europe, including all countries in the Single Euro Payments Area, and in many countries in the Middle East, North Africa and elsewhere. They are often used together with a SWIFT or BIC code, which identifies the bank.","The United States, Canada and Australia do not use IBANs for domestic accounts, relying instead on their own systems, such as routing numbers in the United States. Payments to these countries require different details."],"note":"","total":1500,"prev":{"slug":"hypothesis-test","term":"Hypothesis Test"},"next":{"slug":"identity-theft","term":"Identity Theft"}}')}}]);